// API interface definition for the Hex Single Motor Mini Drive.
// 
// The first 2 bytes of each message contain the message message_code. The remainder 
// of the message contains data as defined below, writting the fields in order.
// as their bit representation, little-endian.

// Note, this file is autogenerated. Use 'npm run build' to regenerate from the 'interface.yaml' spec.

export const VERSION_STRING = "0.114.0";

// Byte length of the version string.
export const VERSION_STRING_SIZE = 64;

// Number of contiguous readouts to store in the history buffer for a snapshot.
export const HISTORY_SIZE = 180;

// Maximum size of a message in bytes; used to allocate buffers for the messages.
export const MAX_MESSAGE_SIZE = 256;

// Number of bytes in the unit test output; should be enough to store the output of the funky atan unit test.
export const UNIT_TEST_OUTPUT_SIZE = 248;

// Number of driver states that can be queued with a single command.
export const DRIVE_SCHEDULE_SIZE = 12;

// Scaling factor for the current units; although values are in float32 there are internal sections of code
// that use Q1.31 integer math so we must be able to convert between the float32 and Q1.31 representations
// without losing too much precision.
export const CURRENT_UNITS_PER_AMP = 1000000;

// Scaling factor for the voltage units; although values are in float32 there are internal sections of code
// that use Q1.31 integer math so we must be able to convert between the float32 and Q1.31 representations
// without losing too much precision.
export const VOLTAGE_UNITS_PER_VOLT = 1000000;

// Clock frequency of the microcontroller. We need this value to compute the time unit for the driver.
// Each tick is ~6.94ns.
export const CLOCK_FREQUENCY = 144000000;

// Number of clock cycles for one section of the PWM counter. The PWM is a triangle wave that goes from
// 0 to PWM_BASE and back to 0. The PWM frequency is CLOCK_FREQUENCY / (2 * PWM_BASE).
// !The time unit for the driver is the duration of a whole PWM cycle, which is 2 * PWM_BASE clock cycles.
export const PWM_BASE = 3072;

// Flag to enable the U output of the driver.
export const ENABLE_U_OUTPUT = 1;

// Flag to enable the V output of the driver.
export const ENABLE_V_OUTPUT = 2;

// Flag to enable the W output of the driver.
export const ENABLE_W_OUTPUT = 4;

// Flag to enable the Z output of the driver.
export const ENABLE_Z_OUTPUT = 8;

// Version information of the driver.
export class Version extends Array {
  constructor(init) {
    if (Array.isArray(init)) {
      super(...init);
    } else {
      super(64);
    }
  }
}


function write_Version(value) {
  const buffer = new Uint8Array(64);
  const view = new DataView(buffer.buffer);
  let offset = 0;
  for (let i = 0; i < 64; i++) {
    view.setUint8(offset, value[i])
    offset += 1;
  }
  return buffer;
}

function read_Version(view, offset = 0) {
  let result = new Version();
  for (let i = 0; i < 64; i++) {
    result[i] = view.getUint8(offset);
    offset += 1;
  }
  return result;
}

