// Basic readout of the motor driver internal state; can be recorded contiguously
// into a history buffer after a commanded event.
export class Readout {
  // Readout number; used to identify the readout in the history.
  readout_number;
  // PWM counter value at the start of the control update. Should occur immediately 
  // after the halfway point.
  cycle_start_tick;
  // PWM counter value at the end of the control update. Should occur immediately 
  // before the halfway point.
  cycle_end_tick;
  // Whether we have an angle fix and how confident it is.
  angle_fix;
  // Driver state flags; packed into a 16-bit value.
  state_flags;
  // Raw reference readout (ADC value); this is the reference voltage for the current 
  // readouts as seen by the amplifier. The phase readouts are relative to this voltage
  // so if this is quite noisy then the phases will also be noisy. We must track it!
  ref_readout;
  // The PWM voltage on the direct axis.
  direct_drive_voltage;
  // The PWM voltage for the quadrature drive output.
  quadrature_drive_voltage;
  // Current in DQ0 coordinates; aligned with the rotor angle.
  direct_current;
  // Current in DQ0 coordinates; crossed with the rotor angle.
  quadrature_current;
  // The current common mode in the DQ0 transform.
  zero_current;
  // Difference in direct current compared to the previous readout.
  direct_current_diff;
  // Difference in quadrature current compared to the previous readout.
  quadrature_current_diff;
  // Best estimate for the rotor magnetic angle.
  angle;
  // Rotor magnetic angle that was used to calculate the readout.
  predicted_angle;
  // Best estimate for the rotor magnetic angular speed.
  angular_speed;
  // Instantaneous VCC voltage readout (ADC value); from resistance divider.
  vcc_voltage;
  // Angle of the EMF voltage vector.
  emf_voltage_angle;
  // Variance of the EMF angle error; used to determine if the EMF angle is too noisy to update.
  emf_angle_variance;
  // EMF voltage magnitude. The EMF is always along the beta direction, but we can have 
  // errors in the measurements and the rotor position and thus we see alpha component 
  // as well. We can rotate the EMF voltage vector fully to the beta direction and get 
  // closer to the actual EMF voltage magnitude.
  emf_voltage_magnitude;
  // Angular speed of the EMF voltage vector.
  emf_voltage_angular_speed;
  // Variance of the EMF angular speed; used to determine if the EMF speed is too noisy to update.
  emf_angular_speed_variance;
  // Instantaneous temperature readout (ADC value); from the temperature sensor.
  temperature;
  // Angle of the current vector relative to the rotor angle.
  current_angle_offset;
  // Magnitude of the current vector.
  current_magnitude;
  // Estimated near-instantaneous total power draw of the motor.
  total_power;
  // Long duration average of the total power; used to limit the maximum power draw.
  total_power_average;
  // Long duration average of the resistive power; used to limit the maximum resistive power.
  resistive_power_average;
  // Integrated number of EMF deduced rotor angle rotations since startup.
  rotations;
  // Active PWM duty for the motor outputs.
  active_pwm;
  // Angle of the active drive vector.
  active_angle;
  
  constructor(init) {Object.assign(this, init);}
}

